import{_ as a,o as n,c as e,a3 as t}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"首次启动与目录","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/first-run.md","filePath":"deploy/first-run.md","lastUpdated":1791133906000}'),l={name:"deploy/first-run.md"};function o(i,s,d,p,r,c){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="首次启动与目录" tabindex="-1">首次启动与目录 <a class="header-anchor" href="#首次启动与目录" aria-label="Permalink to &quot;首次启动与目录&quot;">​</a></h1><p>首次启动游戏时，框架会自动在手机上建立一套目录。本篇说明这些文件是什么、能不能删、出问题去哪找。</p><h2 id="框架建了什么" tabindex="-1">框架建了什么 <a class="header-anchor" href="#框架建了什么" aria-label="Permalink to &quot;框架建了什么&quot;">​</a></h2><p>启动游戏后，框架在你的数据目录下建立这些内容：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Android/data/&lt;游戏包名&gt;/files/</span></span>
<span class="line"><span>├── mods/                          ← Mod 存放目录</span></span>
<span class="line"><span>│   ├── _示例Mod_可删除/            ← 自动生成的示例，教你格式</span></span>
<span class="line"><span>│   │   └── mod.json</span></span>
<span class="line"><span>│   └── &lt;你自己加的 Mod&gt;/</span></span>
<span class="line"><span>│       └── mod.json</span></span>
<span class="line"><span>├── AFMOD_settings.json            ← 面板设置（位置、展开状态）</span></span>
<span class="line"><span>├── AFMOD_log.txt                  ← 运行日志</span></span>
<span class="line"><span>└── rncampaignInfo.dat             ← 游戏原有存档（框架不动它）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h2 id="逐个说明" tabindex="-1">逐个说明 <a class="header-anchor" href="#逐个说明" aria-label="Permalink to &quot;逐个说明&quot;">​</a></h2><h3 id="mods-目录" tabindex="-1"><code>mods/</code> 目录 <a class="header-anchor" href="#mods-目录" aria-label="Permalink to &quot;\`mods/\` 目录&quot;">​</a></h3><p><strong>框架扫描 Mod 的地方。</strong> 规则：</p><ul><li>每个 Mod 是 <code>mods/</code> 下的<strong>一个子文件夹</strong>。</li><li>文件夹里必须有 <code>mod.json</code>。</li><li><strong>不能直接把 <code>mod.json</code> 丢在 <code>mods/</code> 根目录</strong>（框架不会读）。</li></ul><p>正确的：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mods/</span></span>
<span class="line"><span>├── 我的强化主炮/</span></span>
<span class="line"><span>│   └── mod.json       ✅ 子文件夹里，能读到</span></span>
<span class="line"><span>└── 悠闲模式/</span></span>
<span class="line"><span>    └── mod.json       ✅</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>错误的：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mods/</span></span>
<span class="line"><span>└── mod.json           ❌ 直接在根目录，读不到</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">文件夹叫什么名字都行</p><p>框架读的是 <code>mod.json</code> 里的 <code>modName</code> 字段，文件夹名只用于区分和管理（比如禁用时会生成 <code>文件夹名_disabled.txt</code>）。所以用中文名也没问题。</p></div><h3 id="示例mod-可删除" tabindex="-1"><code>_示例Mod_可删除/</code> <a class="header-anchor" href="#示例mod-可删除" aria-label="Permalink to &quot;\`_示例Mod_可删除/\`&quot;">​</a></h3><p>首次启动自动生成的示例 Mod，里面是一个带注释的 <code>mod.json</code>，演示了各种字段怎么写。</p><ul><li><strong>可以直接删掉</strong>，不影响框架运行。</li><li>建议<strong>先看一眼内容</strong>再删，格式就懂了。</li></ul><p>以 <code>_</code> 开头的文件夹框架会特殊处理，不会被当成正常 Mod 加载。</p><h3 id="afmod-settings-json" tabindex="-1"><code>AFMOD_settings.json</code> <a class="header-anchor" href="#afmod-settings-json" aria-label="Permalink to &quot;\`AFMOD_settings.json\`&quot;">​</a></h3><p>面板自身的设置，比如：</p><ul><li>悬浮窗的<strong>位置</strong>（你拖到哪，下次还在哪）</li><li>各个参数分组<strong>是否展开</strong></li><li>上次停留在<strong>哪个页面</strong></li></ul><div class="warning custom-block"><p class="custom-block-title">悬浮窗位置存了版本号</p><p>如果框架升级导致界面布局变化，旧位置可能不合适（比如压到新按钮上）。这时设置文件里会有一个版本号字段，框架检测到版本不符会<strong>重置到安全位置</strong>。所以你不用手动改这个文件。</p></div><h3 id="afmod-log-txt" tabindex="-1"><code>AFMOD_log.txt</code> <a class="header-anchor" href="#afmod-log-txt" aria-label="Permalink to &quot;\`AFMOD_log.txt\`&quot;">​</a></h3><p>运行日志。框架把加载了哪些 Mod、改了哪些参数、有没有冲突、引擎有没有报错，都写在这里。</p><ul><li>游戏内「日志」页可以直接看，也能一键导出。</li><li><strong>排查问题的第一现场</strong>，详见 <a href="/AtlanticFleetSite/docs/use/log-page">日志页：自查问题</a>。</li></ul><div class="tip custom-block"><p class="custom-block-title">为什么日志要落盘</p><p>因为只存内存的日志，游戏一关就没了。真机上遇到问题想找人帮忙看，没有文件就没有证据。所以框架的日志策略是：<strong>累积到一定条数写一次磁盘，退出时补刷，超过 200 KB 自动截断保留最近的</strong>。</p></div><h2 id="三个位置的分工" tabindex="-1">三个位置的分工 <a class="header-anchor" href="#三个位置的分工" aria-label="Permalink to &quot;三个位置的分工&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph Disk[&quot;手机存储&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        M[&quot;mods/&lt;br/&gt;你写的配置&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        S[&quot;AFMOD_settings.json&lt;br/&gt;界面偏好&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        L[&quot;AFMOD_log.txt&lt;br/&gt;运行记录&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    M --&gt;|&quot;启动时读取&lt;br/&gt;决定改什么&quot;| G[&quot;游戏运行时&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S --&gt;|&quot;面板打开时读取&lt;br/&gt;决定长什么样&quot;| G</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G --&gt;|&quot;运行时产生&lt;br/&gt;随时追加&quot;| L</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>记住一句话：<strong><code>mods/</code> 是输入，<code>AFMOD_log.txt</code> 是输出，<code>AFMOD_settings.json</code> 是界面偏好。</strong></p><h2 id="找不到目录怎么办" tabindex="-1">找不到目录怎么办 <a class="header-anchor" href="#找不到目录怎么办" aria-label="Permalink to &quot;找不到目录怎么办&quot;">​</a></h2><p><code>Android/data</code> 在安卓 11+ 被系统限制了访问，常见表现是「文件夹是空的」或「打不开」。</p><p>解决办法：</p><ul><li><strong>推荐</strong>：用 MT管理器（申请了对应权限，能进 <code>Android/data</code>）。</li><li>或者用数据线连电脑访问。</li><li>或者<strong>根本不进目录</strong> —— 框架提供了完整的面板操作，装 Mod 可以直接粘贴分享码，看日志可以在游戏内看。详见 <a href="/AtlanticFleetSite/docs/deploy/install-mod">安装 Mod 的三种方式</a>。</li></ul><h2 id="清理建议" tabindex="-1">清理建议 <a class="header-anchor" href="#清理建议" aria-label="Permalink to &quot;清理建议&quot;">​</a></h2><p>想清理的话，各文件的处理方式：</p><table tabindex="0"><thead><tr><th>文件</th><th>能删吗</th><th>后果</th></tr></thead><tbody><tr><td><code>mods/&lt;某Mod&gt;/</code></td><td>✅ 能</td><td>那个 Mod 失效（也可以在面板里禁用，更安全）</td></tr><tr><td><code>_示例Mod_可删除/</code></td><td>✅ 能</td><td>无影响</td></tr><tr><td><code>AFMOD_settings.json</code></td><td>✅ 能</td><td>面板设置重置（位置回到默认、展开状态清空）</td></tr><tr><td><code>AFMOD_log.txt</code></td><td>✅ 能</td><td>历史日志丢失（会重新开始写）</td></tr><tr><td><code>rncampaignInfo.dat</code></td><td>❌ <strong>别删</strong></td><td>这是游戏存档，删了进度就没了</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">框架不会碰游戏存档文件</p><p>框架要改存档时，是通过游戏自己的保存接口，而不是直接改这个文件。所以除了你自己手动删，这个文件不会被框架动到。</p></div>`,37)])])}const b=a(l,[["render",o]]);export{u as __pageData,b as default};
